  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg-page: #0f1117;
  --bg-card: #1a1d27;
  --bg-input: #12141e;
  --border: #2e3248;
  --border-focus: #6c7bff;
  --border-error: #ff5f5f;
  --text-primary: #e8eaf6;
  --text-secondary: #9098b8;
  --text-error: #ff7a7a;
  --text-success: #4dd98a;
  --accent: #6c7bff;
  --accent-hover: #8490ff;
  --btn-text: #fff;
  --radius: 8px;
  --transition: 0.2s ease;
}

body {
  background: var(--bg-page);
  color: var(--text-primary);
  font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 2rem 1rem;
}

a.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--accent);
  color: var(--btn-text);
  padding: 0.5rem 1rem;
  border-radius: var(--radius);
  font-weight: 600;
  text-decoration: none;
  z-index: 100;
}

a.skip-link:focus {
  top: 1rem;
}

.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 2.5rem 2rem;
  width: 100%;
  max-width: 480px;
}

.card__header {
  margin-bottom: 2rem;
}

.card__title {
  font-size: 1.6rem;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 0.25rem;
}

.card__subtitle {
  font-size: 0.925rem;
  color: var(--text-secondary);
}

.form-field {
  margin-bottom: 1.25rem;
}

.form-field label {
  display: block;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-secondary);
  margin-bottom: 0.4rem;
  letter-spacing: 0.03em;
  text-transform: uppercase;
}

.required-mark {
  color: #ff7a7a;
  margin-left: 0.2rem;
  aria-hidden: true;
}

.form-field input {
  display: block;
  width: 100%;
  background: var(--bg-input);
  border: 1.5px solid var(--border);
  border-radius: var(--radius);
  color: var(--text-primary);
  font-size: 1rem;
  padding: 0.65rem 0.9rem;
  transition: border-color var(--transition), box-shadow var(--transition);
  outline: none;
}

.form-field input::placeholder {
  color: #4a5070;
}

.form-field input:focus {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(108, 123, 255, 0.25);
  outline: 2px solid transparent;
}

.form-field input[aria-invalid="true"] {
  border-color: var(--border-error);
}

.form-field input[aria-invalid="true"]:focus {
  box-shadow: 0 0 0 3px rgba(255, 95, 95, 0.25);
}

.field-hint {
  font-size: 0.8rem;
  color: var(--text-secondary);
  margin-top: 0.35rem;
}

.field-message {
  font-size: 0.8rem;
  margin-top: 0.35rem;
  min-height: 1.2em;
  display: flex;
  align-items: center;
  gap: 0.3rem;
}

.field-message:empty {
  display: none;
}

.field-message--error {
  color: var(--text-error);
}

.field-message--success {
  color: var(--text-success);
}

.btn-submit {
  display: block;
  width: 100%;
  margin-top: 1.75rem;
  padding: 0.8rem 1.5rem;
  background: var(--accent);
  color: var(--btn-text);
  font-size: 1rem;
  font-weight: 700;
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background var(--transition), box-shadow var(--transition);
  letter-spacing: 0.02em;
}

.btn-submit:hover {
  background: var(--accent-hover);
}

.btn-submit:focus-visible {
  outline: 3px solid var(--border-focus);
  outline-offset: 3px;
  box-shadow: 0 0 0 5px rgba(108, 123, 255, 0.3);
}

.btn-submit:active {
  transform: translateY(1px);
}

/* Success banner */
.form-success {
  display: none;
  text-align: center;
  padding: 1rem 0 0.5rem;
}

.form-success.is-visible {
  display: block;
}

.form-success__icon {
  font-size: 2.5rem;
  margin-bottom: 0.5rem;
}

.form-success__title {
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--text-success);
  margin-bottom: 0.25rem;
}

.form-success__body {
  font-size: 0.9rem;
  color: var(--text-secondary);
}

/* Live region */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* Reflow at 320px */
@media (max-width: 360px) {
  .card {
    padding: 1.5rem 1rem;
  }

  .card__title {
    font-size: 1.3rem;
  }
}

/* Forced colors */
@media (forced-colors: active) {
  .form-field input {
    border: 2px solid ButtonBorder;
    background: Canvas;
    color: CanvasText;
  }

  .form-field input:focus {
    outline: 3px solid Highlight;
    box-shadow: none;
  }

  .btn-submit {
    background: ButtonFace;
    color: ButtonText;
    border: 2px solid ButtonBorder;
  }

  .btn-submit:focus-visible {
    outline: 3px solid Highlight;
  }
}
