      el: document.getElementById('phone'),
      msg: document.getElementById('phone-msg'),
      validate(val) {
        if (!val.trim()) return null; // optional
        if (!/^\+?[\d\s\-().]{7,20}$/.test(val.trim()))
          return 'Enter a valid phone number (e.g. +1 555-123-4567).';
        return null;
      },
    },
  };

  function showError(field, message) {
    field.el.setAttribute('aria-invalid', 'true');
    field.msg.textContent = message;
    field.msg.className = 'field-message field-message--error';
  }

  function showSuccess(field) {
    field.el.setAttribute('aria-invalid', 'false');
    field.msg.textContent = '✓ Looks good';
    field.msg.className = 'field-message field-message--success';
  }

  function clearMessage(field) {
    field.el.removeAttribute('aria-invalid');
    field.msg.textContent = '';
    field.msg.className = 'field-message';
  }

  function validateField(key) {
    const field = fields[key];
    const error = field.validate(field.el.value);
    if (error) {
      showError(field, error);
      return false;
    }
    // Only show success tick if the field has a value
    if (field.el.value.trim()) {
      showSuccess(field);
    } else {
      clearMessage(field);
    }
    return true;
  }

  // Validate on blur (after first interaction)
  Object.keys(fields).forEach((key) => {
    const field = fields[key];

    field.el.addEventListener('blur', () => {
      validateField(key);
    });

    // Re-validate on input once the field has been blurred
    field.el.addEventListener('input', () => {
      if (field.el.getAttribute('aria-invalid') !== null) {
        validateField(key);
      }
    });
  });

  form.addEventListener('submit', (e) => {
    e.preventDefault();

    let firstInvalid = null;
    let allValid = true;

    Object.keys(fields).forEach((key) => {
      const valid = validateField(key);
      if (!valid && !firstInvalid) {
        firstInvalid = fields[key].el;
        allValid = false;
      }
    });

    if (!allValid) {
      firstInvalid.focus();
      announce('Please fix the errors in the form before submitting.');
      return;
    }

    showSuccessBanner();
  });

  function showSuccessBanner() {
    const successEl = document.getElementById('form-success');
    form.setAttribute('aria-hidden', 'true');
    form.style.display = 'none';
    successEl.classList.add('is-visible');
    successEl.removeAttribute('aria-hidden');
    document.getElementById('success-heading').focus();
    announce('Your message has been sent. We will get back to you shortly.');
  }

  function announce(message) {
    liveRegion.textContent = '';
    // Force a DOM reflow so AT picks up the new text
    void liveRegion.offsetWidth;
    liveRegion.textContent = message;
  }
})();
